import {pipGroups,pipPalette,standardPip,normalizePip,attachPip,matchPipCrew,pipSvg} from './pip.js';
export function mountPipWorkshop({root,config,crewIndex,onChange,onDone,onAnalyze,onHelp,onSpeak}){
 let value=normalizePip(config),tab='travel',drag=null;
 const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e};
 const note=make('p','pip-note','Tap a part to fit it. You can also drag it onto PIP.');
 const body=make('div','pip-workshop-body'),blueprint=make('div','pip-blueprint'),preview=make('div','pip-preview');preview.id='pip-dropzone';preview.setAttribute('role','img');blueprint.append(make('span','pip-blueprint-title','PIP // BUDDY SCHEMATIC'),preview,make('p','pip-blueprint-caption','My buddy. Always ready to explore.'));
 const rack=make('div','pip-rack'),tabs=make('div','pip-tabs'),parts=make('div','pip-parts');tabs.setAttribute('role','group');tabs.setAttribute('aria-label','PIP part categories');rack.append(tabs,parts);body.append(blueprint,rack);const status=make('p','pip-workshop-status','Standard PIP. Hover ready.');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 const footer=make('div','pip-footer');root.append(note,body,status,footer);
 function button(label,fn,parent,touch=true){const b=make('button',null,label);b.type='button';let handled=-Infinity;b.onclick=e=>{if(e.detail===0||performance.now()-handled>350)fn(e)};if(touch)b.addEventListener('pointerup',e=>{if(e.pointerType==='touch'){e.preventDefault();handled=performance.now();requestAnimationFrame(()=>fn(e))}});parent.append(b);return b}
 const summary=()=>pipGroups.map(g=>g.parts.find(p=>p.id===value[g.id]).name).join(', ')+', '+pipPalette.find(p=>p.id===value.color).name;
 function update(message){preview.innerHTML=pipSvg(value);preview.setAttribute('aria-label','PIP: '+summary());onChange({...value});status.textContent=message;renderParts();}
 function fit(slot,id){value=attachPip(value,slot,id);const part=slot==='color'?pipPalette.find(p=>p.id===id):pipGroups.find(g=>g.id===slot).parts.find(p=>p.id===id);update('Fitted: '+part.name+'. '+(part.note||'PIP keeps this color until I change it.'));}
 function clearDrag(){if(drag){drag.ghost?.remove();drag=null;}blueprint.classList.remove('drop-ready');}
 function attachDrag(b,slot,id){let ignoreClickUntil=0;b.addEventListener('click',e=>{if(e.detail!==0&&performance.now()<ignoreClickUntil){e.preventDefault();e.stopImmediatePropagation();}},true);b.style.touchAction='none';b.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,active:false,slot,part:id,button:b};b.setPointerCapture(e.pointerId)});b.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>12)drag.active=true;if(!drag.active)return;e.preventDefault();if(!drag.ghost){drag.ghost=make('div','pip-drag-ghost','＋ '+b.dataset.partName);drag.ghost.setAttribute('aria-hidden','true');root.append(drag.ghost)}drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';blueprint.classList.add('drop-ready');});b.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const active=drag.active,r=blueprint.getBoundingClientRect(),inside=e.clientX>=r.left-20&&e.clientX<=r.right+20&&e.clientY>=r.top-20&&e.clientY<=r.bottom+20;clearDrag();if(!active&&e.pointerType==='touch'){e.preventDefault();ignoreClickUntil=performance.now()+350;requestAnimationFrame(()=>fit(slot,id));}if(active){ignoreClickUntil=performance.now()+350;// Keep the touched node alive through touchend so the next gesture gets its click.
if(inside)requestAnimationFrame(()=>fit(slot,id));else status.textContent='Part put back. Tap it any time to attach it.';}});b.addEventListener('pointercancel',clearDrag);b.addEventListener('lostpointercapture',clearDrag);}
 function renderParts(){parts.classList.toggle('pip-colors',tab==='color');parts.replaceChildren();const group=pipGroups.find(g=>g.id===tab),items=tab==='color'?pipPalette:group.parts;for(const part of items){const b=button('',()=>fit(tab,part.id),parts,false);b.dataset.part=part.id;b.dataset.partName=part.name;b.setAttribute('aria-label',part.name);b.setAttribute('aria-pressed',String(value[tab]===part.id));if(tab==='color'){const swatch=make('span','pip-swatch');swatch.style.background=part.color;b.append(swatch)}else{const icon=make('span','pip-part-icon',part.icon);icon.setAttribute('aria-hidden','true');b.append(icon)}b.append(make('span',null,part.name));attachDrag(b,tab,part.id);}}
 for(const g of [...pipGroups,{id:'color',title:'Colors',icon:'🎨'}]){const b=button(g.icon+' '+g.title,()=>{tab=g.id;for(const t of tabs.children)t.setAttribute('aria-pressed',String(t===b));renderParts()},tabs);b.dataset.pipTab=g.id;b.setAttribute('aria-pressed',String(tab===g.id));}
 button('✓ Explore with PIP',onDone,footer);button('🎨 Match my J.A.C.C.',()=>{value=matchPipCrew(value,crewIndex());update('PIP matches my astronaut suit.')},footer);button('↺ Standard',()=>{value=standardPip();update('Standard PIP restored.')},footer);button('🔎 Analyze',onAnalyze,footer);button('🤖 Help',onHelp,footer);button('🔊 Listen',()=>onSpeak('Tap a part to fit it. You can also drag it onto PIP. '+summary()),footer);
 preview.innerHTML=pipSvg(value);preview.setAttribute('aria-label','PIP: '+summary());renderParts();
}
